-- A grade's own terms on a sheet (whole days); a grade with no row takes the sheet's terms.
CREATE TABLE sheet_grade_terms (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    grade CHAR(1) NOT NULL,
    terms INT NOT NULL,
    CHECK (terms >= 0)
);
CREATE UNIQUE INDEX sheet_grade_terms_sheet_grade ON sheet_grade_terms (sheet_id, grade);

-- A claim's due-by is fixed when it is added: its date plus the terms of its person's grade in force
-- on that date. Existing claims take their date plus their sheet's terms.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = c.sheet_id), c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- A sheet's grace days: when the sheet's today is changed, every open period whose to-date plus them
-- is before the new today is closed. Null (blank) is off.
ALTER TABLE sheet ADD COLUMN grace_days INTEGER;
-- A sheet's entry date: while it is set, a new claim given no date (on the claim form, the quick-add
-- bar, a pasted line or a correction) is dated it rather than the sheet's today. Null (blank) is off.
ALTER TABLE sheet ADD COLUMN entry_date DATE;
-- An OPEN or PENDING claim can be reminded once per sheet's today: the last day a reminder was
-- written for it, or null when none was.
ALTER TABLE claim ADD COLUMN reminded_on DATE;

