        LocalDate asOf = AsOf.parse(asOfHeader);
        if (asOf != null) {
            return service.listAsOf(sheetId.trim(), asOf).stream().map(PeriodView::of).toList();
        }
        return service.list(sheetId.trim()).stream().map(PeriodView::of).toList();
